from pathlib import Path
import json,subprocess,hashlib
ROOT=Path(__file__).resolve().parent;OUT=Path('/path/to/local-assets');config=json.loads((ROOT/'comparison.json').read_text());receipt=json.loads((OUT/'comparison-capture-receipt.json').read_text());assert receipt['completed'] and not receipt['errors'] and receipt['cleanup']['status']=='verified'
def stamp(t):
 ms=round(t*1000);h,ms=divmod(ms,3600000);m,ms=divmod(ms,60000);s,ms=divmod(ms,1000);return f'{h:02d}:{m:02d}:{s:02d},{ms:03d}'
offset=0;cues=[]
for scene,render in zip(config['segments'],receipt['segments']):
 assert scene['audioQA']['normalizedScriptSimilarity']>.95 and scene['audioQA']['lastWordIncluded']
 for c in scene['captionCues']:cues.append({'start':offset+c['start'],'end':offset+c['end'],'text':c['text']})
 offset+=render['duration']
cues[-1]['end']=offset
(OUT/'comparison-narration.srt').write_text('\n\n'.join(f"{i+1}\n{stamp(c['start'])} --> {stamp(c['end'])}\n{c['text']}"for i,c in enumerate(cues))+'\n');(OUT/'comparison-narration.vtt').write_text('WEBVTT\n\n'+'\n\n'.join(f"{stamp(c['start']).replace(',', '.')} --> {stamp(c['end']).replace(',', '.')}\n{c['text']}"for c in cues)+'\n');(OUT/'comparison-narration.txt').write_text('\n\n'.join(s['answer']for s in config['segments'])+'\n')
master=OUT/'three-route-comparison-master.mp4';final=OUT/'three-route-comparison.mp4';subprocess.run(['ffmpeg','-y','-v','error','-i',str(master),'-i',str(OUT/'comparison-narration.srt'),'-map','0:v','-map','0:a','-map','1:0','-c:v','copy','-c:a','copy','-c:s','mov_text','-metadata:s:s:0','language=eng','-movflags','+faststart',str(final)],check=True);subprocess.run(['ffmpeg','-v','error','-i',str(final),'-f','null','-'],check=True);probe=json.loads(subprocess.check_output(['ffprobe','-v','quiet','-show_streams','-show_format','-of','json',str(final)]));(OUT/'comparison-ffprobe.json').write_text(json.dumps(probe,indent=2));v,a,sub=probe['streams'];assert v['r_frame_rate']=='30/1' and v['pix_fmt']=='yuv420p' and a['sample_rate']=='48000';assert abs(float(v['duration'])-float(a['duration']))<=.11 and abs(float(v['duration'])-float(sub['duration']))<=.1;data=final.read_bytes();assert data.index(b'moov')<data.index(b'mdat')
for t in [2.5,7,12,25,28,33,39,49,52,57,65,76]:subprocess.run(['ffmpeg','-y','-v','error','-ss',str(t),'-i',str(final),'-frames:v','1',str(OUT/f'comparison-probe-{str(t).replace(".","-")}.png')],check=True)
loud=subprocess.run(['ffmpeg','-hide_banner','-i',str(final),'-vn','-af','ebur128=peak=true','-f','null','-'],capture_output=True,text=True);(OUT/'comparison-audio-loudness.txt').write_text(loud.stderr[-1800:]);manifest={'file':str(final),'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),'duration':float(v['duration']),'sourceRenderedFPS':15,'deliveryFPS':30,'frames':int(v['nb_frames']),'voice':config['voice'],'subtitleCues':len(cues),'captions':'Native on-screen authoritative text aligned to actual ASR word times; embedded English,SRT,VTT included','segments':receipt['segments'],'qa':{'fullDecode':'pass','fastStart':'pass','pixelFormat':'yuv420p','audioSampleRate':48000,'avDriftSeconds':abs(float(v['duration'])-float(a['duration'])),'browserErrors':[],'sourceGeometry':'Original Ryo+room byte-identical; full imported30720/185068-face meshes, no mesh decimation','scope':config['purpose'],'visualProbes':'Extracted; inspection pending','perceptualAudio':'Pending exact-file model listening, no human headphone review'},'limits':config['limits']};(OUT/'comparison-delivery-manifest.json').write_text(json.dumps(manifest,indent=2));print(json.dumps({'file':str(final),'duration':manifest['duration'],'bytes':len(data),'sha256':manifest['sha256'],'avDriftSeconds':manifest['qa']['avDriftSeconds']}))
